import 'dart:ui';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:get_storage/get_storage.dart';import 'app_state.dart';class VisionCubit extends Cubit<VisionState> {  final GetStorage _box;  bool isShowingInterstitial = false;  VisionCubit(this._box) : super(VisionState.initial()) {    _loadInitialState();  }  void _loadInitialState() {    final theme = _box.read('theme') ?? 'light';    final isPremium = _box.read('isPremium') ?? false;    // Language setup    String? savedLanguage = _box.read('language');    const supportedLanguages = ['en', 'de', 'fr', 'ar', 'ja', 'es', 'af', 'pt', 'id'];    String language;    if (savedLanguage != null && supportedLanguages.contains(savedLanguage)) {      language = savedLanguage;    } else {      final systemLang = PlatformDispatcher.instance.locale.languageCode;      language = supportedLanguages.contains(systemLang) ? systemLang : 'en';    }    int launchCount = _box.read('launchCount') ?? 0;    emit(      state.copyWith(        selectedTheme: theme,        selectedLanguage: language,        isPremium: isPremium,        locale: Locale(language),        launchCount: launchCount,      ),    );  }  void changeTheme(String theme) {    _box.write('theme', theme);    emit(state.copyWith(selectedTheme: theme));  }  void changeLanguage(String languageCode) {    if (languageCode.isEmpty) return;    _box.write('language', languageCode);    emit(      state.copyWith(        selectedLanguage: languageCode,        locale: Locale(languageCode),      ),    );  }  void setPremium(bool premium) {    _box.write('isPremium', premium);    emit(state.copyWith(isPremium: premium));  }  void increaseLaunchCount() {    int count = state.launchCount + 1;    _box.write('launchCount', count);    emit(state.copyWith(launchCount: count));  }}